import { registerSW } from "virtual:pwa-register";

/**
 * Registers the Workbox service worker generated by vite-plugin-pwa.
 * `registerType: "autoUpdate"` (vite.config.ts) activates new versions on the
 * next load; we also ask the browser to check for one right away.
 */
export function registerServiceWorker() {
  registerSW({
    immediate: true,
    onRegisteredSW(_swUrl, registration) {
      void registration?.update();
    },
    onRegisterError(error) {
      console.error("Service worker registration failed:", error);
    },
  });
}
